import mongoose, { Schema, Document } from 'mongoose';
import { CHANNELS } from './notification.model';
import { EMAIL_PATTERN, PHONE_PATTERN } from './instructor.model';

export interface ICustomer extends Document {
  customerId: string;
  firstName: string;
  lastName: string;
  address: string;
  phone: string;
  email: string;
  preferredContact: (typeof CHANNELS)[number];
  classBalance: number;
  createdAt: Date;
}

/** A studio customer (UC4). customerId (C00001) is generated by the service; classBalance starts at 0. */
const customerSchema = new Schema<ICustomer>(
  {
    customerId: { type: String, required: true },
    firstName: { type: String, required: [true, 'First name is required'], trim: true },
    lastName: { type: String, required: [true, 'Last name is required'], trim: true },
    address: { type: String, required: [true, 'Address is required'], trim: true },
    phone: {
      type: String,
      required: [true, 'Phone is required'],
      trim: true,
      match: [PHONE_PATTERN, 'Phone is not valid'],
    },
    email: {
      type: String,
      required: [true, 'Email is required'],
      trim: true,
      lowercase: true,
      match: [EMAIL_PATTERN, 'Email is not valid'],
    },
    preferredContact: {
      type: String,
      enum: CHANNELS,
      required: [true, 'Preferred contact is required'],
    },
    // Can go negative when a customer attends without enough classes left (UC6)
    classBalance: { type: Number, default: 0 },
  },
  { timestamps: true }
);

// No two customers share an ID
customerSchema.index({ customerId: 1 }, { unique: true });

export const Customer = mongoose.model<ICustomer>('Customer', customerSchema);
